// Canvas Dodge game implementation
// The HTML page contains a <canvas id="game"></canvas>
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.offsetWidth || 800;
  const height = canvas.height = canvas.offsetHeight || 400;

  // Player state
  const player = {
    x: 80,
    y: height - 30,
    radius: 15,
    vy: 0,
    onGround: true,
    crouching: false,
  };
  const GRAVITY = 0.8;
  const JUMP_VELOCITY = -12;
  const SLIDE_TIME = 300; // ms
  let slideTimer = 0;

  // Obstacles
  const obstacles = [];
  const OBSTACLE_SPEED = 4;
  const OBSTACLE_INTERVAL = 1500; // ms
  let lastObstacle = 0;

  // Score
  let score = 0;
  let startTime = performance.now();

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.code] = true; });
  window.addEventListener('keyup', e => { keys[e.code] = false; });
  canvas.addEventListener('mousedown', () => keys['Space'] = true);
  canvas.addEventListener('mouseup', () => keys['Space'] = false);

  function spawnObstacle() {
    const size = 30 + Math.random() * 40; // width
    const obs = {
      x: width,
      y: height - size,
      w: size,
      h: size,
    };
    obstacles.push(obs);
  }

  function update(dt) {
    // Player controls
    if (keys['ArrowUp'] || keys['Space']) {
      if (player.onGround) {
        player.vy = JUMP_VELOCITY;
        player.onGround = false;
      }
    }
    if (keys['ArrowDown']) {
      if (!player.crouching) {
        player.crouching = true;
        slideTimer = SLIDE_TIME;
      }
    }
    // Slide timer
    if (player.crouching) {
      slideTimer -= dt;
      if (slideTimer <= 0) {
        player.crouching = false;
        slideTimer = 0;
      }
    }
    // Apply gravity
    player.vy += GRAVITY;
    player.y += player.vy;
    // Ground check
    const groundY = height - (player.crouching ? player.radius / 2 : player.radius);
    if (player.y >= groundY) {
      player.y = groundY;
      player.vy = 0;
      player.onGround = true;
    }

    // Obstacles movement & spawn
    const now = performance.now();
    if (now - lastObstacle > OBSTACLE_INTERVAL) {
      spawnObstacle();
      lastObstacle = now;
    }
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= OBSTACLE_SPEED;
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }

    // Collision detection
    for (const o of obstacles) {
      const cx = player.x;
      const cy = player.y;
      const rx = o.x;
      const ry = o.y;
      const rw = o.w;
      const rh = o.h;
      // simple circle-rect collision
      const nearestX = Math.max(rx, Math.min(cx, rx + rw));
      const nearestY = Math.max(ry, Math.min(cy, ry + rh));
      const dx = cx - nearestX;
      const dy = cy - nearestY;
      if (dx * dx + dy * dy < player.radius * player.radius) {
        // Game over: reset
        alert('Game Over! Score: ' + Math.floor(score));
        obstacles.length = 0;
        player.x = 80;
        player.y = height - 30;
        player.vy = 0;
        player.onGround = true;
        player.crouching = false;
        startTime = performance.now();
        score = 0;
        return;
      }
    }

    // Update score
    score = (now - startTime) / 1000;
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Draw player
    ctx.fillStyle = '#0077ff';
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
    ctx.fill();
    // Draw obstacles
    ctx.fillStyle = '#ff3333';
    for (const o of obstacles) {
      ctx.fillRect(o.x, o.y, o.w, o.h);
    }
    // Draw score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
  }

  let lastTime = 0;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    update(dt);
    draw();
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
